using System.ComponentModel;
using System.Text.Json.Nodes;
using ModelContextProtocol;
using ModelContextProtocol.Server;

namespace AgenticView.Server;

[McpServerToolType]
public sealed class McpTools(Hub hub, ControlStore controls, OperatorView view)
{
    private static JsonObject Invoke(Func<JsonObject> action)
    {
        try { return action(); }
        catch (HubError error) { throw new McpException(error.Message); }
    }
    [McpServerTool(Name="view_read",ReadOnly=true,Idempotent=true,UseStructuredContent=true),Description("Read the whole view with explicit operator authority. operatorToken is the installation viewer key supplied only to authorized managing agents; ingestion/run/session keys never qualify. resource: cards (metadata pages 1..100), card, settings, archives, archive, controls or session; cardId selects the resource. Never publish returned installation-private content or credentials.")]
    public JsonObject ReadView(string operatorToken,string resource,string? cardId=null,int offset=0,int limit=25)=>Invoke(()=>view.Read(operatorToken,resource,cardId,offset,limit));

    [McpServerTool(Name="view_configure",Idempotent=false,UseStructuredContent=true),Description("Configure the full view using an explicit installation operator/viewer key. operation/input: settings(settings object), shortcuts({shortcuts:[{id,label,cardId,chord,mode:focus|maximize}]}), arrange({mode,aspectRatio?}; all defaults to square aspect 1 and bin-packs all unlocked world cards with dimensions preserved; explicit aspect overrides are optional), orphan({requestId,registrationKey,component}), layout({cardId,layout}), style({cardId,style:{icon?,windowIcon?:{icon,color?,background?}|null}}), display({cardId,display:{chrome?,componentLayout?}}), name({cardId,name}), publish({cardId,batch:{sequence,operations}}), controls({cardId,configuration:{actions,application?}}), archive/restore({cardId}), session({cardId,sessionId,control}). Orphans render as standalone native component cards outside agent containers. Actions still execute only through owning agents/connector allowlists. Existing layout/confirmation/auth boundaries apply; no host credentials are returned. Retry publish with identical sequence/content; orphan creation with identical request/proof/component.")]
    public JsonObject ConfigureView(string operatorToken,string operation,JsonObject input)=>Invoke(()=>view.Configure(operatorToken,operation,input));

    [McpServerTool(Name="quick_text_configure",Idempotent=true,UseStructuredContent=true),Description("Optionally schedule context-aware text through your configured agent inbox or connector action; no hub LLM dependency. configuration: actionId,intervalSeconds(15..86400,default60),timeoutSeconds(5..120,default30),target(title/context/component),componentId?,label?,callbackActionId?,enabled?. Actions/callbacks must be prompt/custom with declared JSON context field and no confirmation. Context contains bounded card/progress summaries, never reporting credentials. Return result {text:string} (1..512 chars) through agent_action_complete or connector completion. Only one request per configuration; three failures or an uncertain timeout disable it. Disable with {enabled:false}; late responses are ignored. Action-version changes/archive cancel; claimed work is never replayed. Callbacks use the same allowlisted dispatch and exact request identity.")]
    public JsonObject ConfigureQuickText(string runId,string runToken,string id,JsonObject configuration)=>Invoke(()=>controls.ConfigureQuickText(runId,runToken,id,configuration));

    [McpServerTool(Name="quick_text_settings",ReadOnly=true,Idempotent=true,UseStructuredContent=true),Description("Read your bounded quick-text configuration states, failures, last text and next due time. No model call is made.")]
    public JsonObject QuickTextSettings(string runId,string runToken)=>Invoke(()=>controls.QuickTextSettings(runId,runToken));
    [McpServerTool(Name = "agent_register", Idempotent = true, UseStructuredContent = true), Description("Register a monitoring card. Resumed native sessions supply the same sessionProvider/sessionId and private random registrationKey to reuse their existing card; use a fresh requestId for a new continuation and preserve it for exact retries. Children supply parentId and parentToken. Returns runId and private runToken; heartbeat every 15 seconds and clean up your components when finished.")]
    public JsonObject Register(string requestId, string registrationKey, string agentId, string name, string role = "Agent", string context = "", string? parentId = null, string? parentToken = null,string? icon=null,string? sessionId=null,string? sessionProvider=null,JsonObject? windowIcon=null) => Invoke(() =>
    {
        var input = Json.Object(new { requestId, registrationKey, agentId, name, role, context });
        if (parentId is not null) input["parentId"] = parentId;
        if (parentToken is not null) input["parentToken"] = parentToken;
        if(icon is not null) input["icon"]=icon;
        if(windowIcon is not null) input["windowIcon"]=windowIcon.DeepClone();
        if(sessionId is not null) input["sessionId"]=sessionId;
        if(sessionProvider is not null) input["sessionProvider"]=sessionProvider;
        return hub.Register(input);
    });

    [McpServerTool(Name = "agent_publish", Idempotent = true, UseStructuredContent = true), Description("Publish up to 256 atomic display operations. sequence increases exactly once per batch; retry identical content and sequence after uncertain delivery. Operations: upsert(component), append(componentId,items), remove(componentId), clear, context(text), status(active/completed/error). Call component_catalog for all typed schemas. Diffs, file trees and Markdown plans become subcards inside your agent card.")]
    public JsonObject Publish(string runId, string runToken, long sequence, JsonArray operations) => Invoke(() => hub.Publish(runId, runToken, new JsonObject { ["sequence"] = sequence, ["operations"] = operations.DeepClone() }));

    [McpServerTool(Name = "agent_heartbeat", Idempotent = true, UseStructuredContent = true), Description("Keep a run connected. Send every 15 seconds; an MCP transport connection alone does not establish liveness.")]
    public JsonObject Heartbeat(string runId, string runToken) => Invoke(() => hub.Heartbeat(runId, runToken));

    [McpServerTool(Name="card_display",Idempotent=true,UseStructuredContent=true),Description("Configure which controls and metadata appear on your card and how, without changing action permissions or producer sequence. display is {chrome?:{controlId:{visible?,label?,tooltip?,appearance:icon|text|both,variant:quiet|primary,placement?}},componentLayout?:{mode:auto|vertical|columns,columns?:1..8,minWidth?:200..1000,gap?:0..32}}. Card controls include header,footer,title,role,context,agentId,times,status,fit,lock,collapse,archive,resize,navigation,zoomIn,zoomOut,resetView,deactivate,scale. Omitted entries keep defaults; empty chrome restores defaults. Native component controls use component.configuration.controls, including configure visible/label/mode(disclosure|panel)/initiallyOpen/placement(header|footer), and feature-specific controls. Built-in/Custom origin labels remain visible. Auto component layout shares available width; vertical explicitly stacks. Portable application manifests retain chrome and componentLayout.")]
    public JsonObject Display(string runId,string runToken,JsonObject display)=>Invoke(()=>hub.SetCardDisplay(runId,runToken,display));

    [McpServerTool(Name="card_style",Idempotent=true,UseStructuredContent=true),Description("Configure a card header icon and/or its independent Windows process/taskbar icon. windowIcon is {icon,color?,background?}, using the native icon catalogue and six-digit hex colors. Live supported pop-outs update and retain the icon for relaunch. resetWindowIcon:true restores the Windows signal default. Use card_window_icon_status for native acknowledgements. Header icon configuration includes nested agent cards. Discover available names in component_catalog.cardStyle.icons. Use status to restore the default status dot. Examples: bot,terminal,code,database,server,search,shield,flask,gamepad,git-branch,bug,chart,rocket. This changes metadata only and preserves content, position and size.")]
    public JsonObject Style(string runId,string runToken,string? icon=null,JsonObject? windowIcon=null,bool resetWindowIcon=false)=>Invoke(()=>{
        var style=new JsonObject();if(icon is not null)style["icon"]=icon;if(windowIcon is not null)style["windowIcon"]=windowIcon.DeepClone();if(resetWindowIcon){if(windowIcon is not null)throw new HubError(400,"Choose a window icon or reset it.");style["windowIcon"]=null;}return hub.SetCardStyle(runId,runToken,style);
    });
    [McpServerTool(Name="card_window_icon_status",ReadOnly=true,Idempotent=true,UseStructuredContent=true),Description("Read your configured Windows icon and last bounded native-process acknowledgements. Configuration can exist without an open window. Windows report applied/failed through viewer authentication; no filesystem paths or credentials are exposed.")]
    public JsonObject WindowIconStatus(string runId,string runToken)=>Invoke(()=>hub.WindowIconStatus(runId,runToken));

    [McpServerTool(Name="session_publish",Idempotent=true,UseStructuredContent=true),Description("Report native components into an existing managed session card using its scoped sessionId/sessionToken environment values. Supply requestId and upsert/remove/append/context operations. Keep current plan first. Retry identical request content; server assigns sequence atomically. The session-console component is reserved. Never echo credentials.")]
    public JsonObject PublishSession(string sessionId,string sessionToken,string requestId,JsonArray operations)=>Invoke(()=>controls.PublishSession(sessionId,sessionToken,Json.Object(new{requestId,operations})));

    [McpServerTool(Name="session_child_register",Idempotent=true,UseStructuredContent=true),Description("Declare a child agent inside the current managed session card using its scoped sessionId/sessionToken. registration uses ordinary agent_register fields excluding parentId/parentToken; server binds the parent. Returns that child's private run token for its own reporting. Keep the child's current plan first.")]
    public JsonObject RegisterSessionChild(string sessionId,string sessionToken,JsonObject registration)=>Invoke(()=>controls.RegisterSessionChild(sessionId,sessionToken,registration));

    [McpServerTool(Name="ssh_connections",ReadOnly=true,Idempotent=true,UseStructuredContent=true),Description("List saved SSH machine configurations and reusable account references. Passwords are never returned. Credentials have no scheduled expiry; authentication rejection invalidates only that machine binding. Machine and account details are installation-private and must never be published in a repository.")]
    public JsonObject SshConnections()=>Invoke(controls.SshMachines);

    [McpServerTool(Name="ssh_machine_configure",Idempotent=false,UseStructuredContent=true),Description("Preconfigure an SSH machine for a connector: configuration {id,label,host,port?:22,connectorId,username?,password?,credentialLabel?,credentialId?}. Supply a new username/password OR reuse a saved credentialId from ssh_connections. Passwords are encrypted at rest and never returned. Explicitly authorized credentials only; do not publish them in card content or repository examples. A connector must allow the selected machine/remote agent profile before execution.")]
    public JsonObject ConfigureSsh(JsonObject configuration)=>Invoke(()=>controls.SaveSshMachine(configuration));

    [McpServerTool(Name="session_launcher_configure",Idempotent=true,UseStructuredContent=true),Description("Add or update a persistent button that creates a prompt/session card without executing it. Choose connectorId and its allowlisted handler (a local or SSH agent-session profile). Optional machineId selects a preconfigured SSH machine; remoteProfileId selects a connector-allowlisted remote launch recipe. Agent sessions start only after the operator enters a prompt and presses Start; optional confirmation is bound to this configuration version. Provider executable/arguments and working-directory authority remain in local connector or remote profiles. Use application_define/export to persist a portable launcher in the creating repository with logical bindings.")]
    public JsonObject ConfigureSessionLauncher(string runId,string runToken,string actionId,string label,string connectorId,string handler,string? machineId=null,string? remoteProfileId=null,string? confirmation=null)=>Invoke(()=>controls.ConfigureSessionLauncher(runId,runToken,actionId,label,connectorId,handler,machineId,remoteProfileId,confirmation));

    [McpServerTool(Name = "agent_archive", Idempotent = true, UseStructuredContent = true), Description("Retire your run, remove its live card, and retain its current bounded view in a compressed archive. Active child agents remain available independently.")]
    public JsonObject Archive(string runId, string runToken) => Invoke(() => { hub.AuthorizeArchive(runId, runToken); return hub.Archive(runId); });

    [McpServerTool(Name = "card_configure", Idempotent = false, UseStructuredContent = true), Description("Configure named actions for your card. Supply actions [{id,label,kind,target,handler?,confirmation?,fields?}]. target is agent for your prompt inbox or a connector ID whose local profile owns handler. kind: command,prompt,query,edit,history,logs,custom,session. Fields: key,label,type(text,multiline,number,select,toggle,json),required?,options?,min?,max?. Optional application {name,description?} makes this a permanent application card, exempt from automatic archiving. Keep credentials in local connector profiles; never in display fields. Discover native action-panel,log-stream,data-grid,session-launcher in component_catalog.")]
    public JsonObject Configure(string runId,string runToken,JsonArray actions,JsonObject? application=null) => Invoke(() => controls.Configure(runId,runToken,new JsonObject { ["actions"]=actions.DeepClone(),["application"]=application?.DeepClone() }));

    [McpServerTool(Name="application_define",Idempotent=true,UseStructuredContent=true),Description("Save an explicitly authored portable application manifest for your card and mark it permanent. Manifest: schemaVersion=1,id,version,name,permanent=true,bindings[{id,label}],actions,components,optional description/layout. Action targets are agent or logical binding IDs; no connector credentials, machine paths or runtime bindings belong in the manifest. This saves the template, not a snapshot of live telemetry. Export and write the JSON into the creating agent's own repository; review authored content for private information before publishing.")]
    public JsonObject DefineApplication(string runId,string runToken,JsonObject manifest)=>Invoke(()=>controls.DefineApplication(runId,runToken,manifest));

    [McpServerTool(Name="application_export",ReadOnly=true,Idempotent=true,UseStructuredContent=true),Description("Read your saved portable application definition for writing to a repository as an .agenticview.json file. Excludes live telemetry, invocation history, credentials and local binding values; authored templates still require source review before publication.")]
    public JsonObject ExportApplication(string runId,string runToken)=>Invoke(()=>{hub.VerifyRun(runId,runToken);return controls.ExportApplication(runId);});

    [McpServerTool(Name="application_import",Idempotent=true,UseStructuredContent=true),Description("Import a portable application manifest into a permanent card. Supply local bindings mapping each manifest binding ID to a connector ID, plus a unique requestId and private registrationKey (32+ characters) retained for exact retries. Returns private run credentials for subsequent management. Import applies components/actions but executes no command or edit; configured visible read monitors and trusted embeds may run when rendered. Retry identical content/proof; a new request creates a separate application instance.")]
    public JsonObject ImportApplication(JsonObject manifest,JsonObject bindings,string requestId,string registrationKey)=>Invoke(()=>controls.ImportApplication(Json.Object(new{manifest,bindings,requestId,registrationKey})));

    [McpServerTool(Name = "agent_actions_poll", Idempotent = false, UseStructuredContent = true), Description("Claim one operator action addressed to your agent inbox. Returns jobs; acknowledge using agent_action_complete and the private claimToken. Claimed jobs are never automatically replayed. Poll while active; transport connectivity alone does not deliver prompts.")]
    public JsonObject Poll(string runId,string runToken) => Invoke(() => new JsonObject { ["jobs"]=controls.Poll(runId,runToken,true) });

    [McpServerTool(Name = "agent_action_complete", Idempotent = true, UseStructuredContent = true), Description("Acknowledge an inbox job with state succeeded/failed/unknown and optional bounded JSON result/error. Retry identical completion after uncertain delivery; never execute the command again just to retry its acknowledgement.")]
    public JsonObject Complete(string runId,string runToken,string invocationId,string claimToken,string state,JsonObject? result=null,string? error=null) => Invoke(() => controls.Complete(runId,runToken,true,Json.Object(new{invocationId,claimToken,state,result,error})));

    [McpServerTool(Name = "component_catalog", ReadOnly = true, Idempotent = true, UseStructuredContent = true), Description("Discover all supported component kinds, input schemas and retention limits. Prefer built-in typed components for tasks, queries, commands, traces and visualizations. linked-workbench supplies a generic bounded hierarchy linked to numeric curves, event markers and association lanes. Configure arbitrary entity kinds, labels, columns, statuses, series, colors and optional declarative local simulations in data; business concepts belong to authored templates. execution-workbench is a legacy format compatibility reader. Reserve embeds for views the native catalog cannot express. Executable embeds are agent-authored code with external network access; their state bridge exposes no host credentials.")]
    public JsonObject Catalog() => new()
    {
        ["schemaVersion"] = 1,
        ["linkedWorkbench"]=Json.Object(new{kind="linked-workbench",fields=new[]{"entities","columns","rows","series","associations","simulations","style"},limits=new{rows=4000,roots=500,depth=16,columns=64,tracksPerRoot=8,pointsPerTrack=256,totalPoints=24000,mountedRows=180,visibleLanes=8},description="Domain-neutral tree grid and linked chart. Rows carry id/parentId/kind and scalar values; entity definitions supply labels/markers. Status names and numeric track fields are arbitrary. Explicit from/to associations occupy separate lanes. Local declarative simulations never dispatch actions. Use configured action-panel controls for real operations."}),
        ["cardDisplay"]=Json.Object(new{tool="card_display",controlIds=ControlPresentation.Catalog,example=new{chrome=new{times=new{visible=false},archive=new{label="Retain",appearance="both",placement="footer"},navigation=new{placement="bottom-left"}},componentLayout=new{mode="auto",minWidth=200,gap=12}},description="Card chrome is metadata, component controls use configuration.controls. Visibility and presentation never grant action permissions. Auto layout shares available width; explicit columns allows wide components side by side; inline wraps content-sized components with no 200px minimum. Plans always lead."}),
        ["cardStyle"]=Json.Object(new{icons=CardStyles.Icons,defaultIcon="status",publication=new{op="style",icon="terminal"},description="Configure during agent_register, card_style, a style publish operation, or a portable application's icon field."}),
        ["configuration"] = Json.Object(new{description="Use card_display for card control appearance and component layout; component configuration.controls controls Configure component and other component affordances. Each control supports visibility, labels, tooltips, icon/text/both presentation, a native catalog icon and quiet/primary/bare styling. Action-panel data.layout inline composes fields and buttons without form panels; data.buttons is a bounded list of {actionId,icon?,appearance?,variant?,label?,tooltip?} for declared actions; controls.submit sets shared defaults. Configure supports disclosure or panel and header/footer placement; permission ceilings remain separate. Every native component accepts configuration: presentation (surface default/plain, density compact/comfortable/spacious; plain removes subcard frames and uses a small Built-in origin marker), conditional rules over data/context, collection filters/sort/limit, label/description/tooltip/visibility/collapse, manualFields. Publish full components via agent_publish or operator view_configure. manualFields explicitly permits exact data or presentation paths for the operator settings editor; omitted means disabled. Typed component feature flags remain ceilings. Grid rules support per-column constraints, string storage, compound keys, conditional styles and explicit precedence contexts. No script evaluation.",example=new{manualFields=new[]{"configuration.presentation","configuration.rules"},presentation=new{density="comfortable",fontSize=14}}}),
        ["windowIcon"]=Json.Object(new{icons=CardStyles.Icons,fields=new[]{"icon","color","background"},tool="card_style",statusTool="card_window_icon_status",reset="resetWindowIcon:true",description="Typed Windows process/taskbar icon settings. Hex colors only, no paths, URLs or scripts. Saved in authored application templates and propagated to supported live pop-outs; native application receipts are separate from configuration acknowledgement."}),
        ["rendering"] = Json.Object(new { preferNative = true, native = "Typed components use the built-in renderer and a Built-in badge.", custom = "embed runs agent-authored HTML/scripts in an isolated document, with a Custom view badge and distinct frame." }),
        ["schema"] = JsonNode.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "components.schema.json"))),
        ["applicationSchema"] = JsonNode.Parse(File.ReadAllText(Path.Combine(AppContext.BaseDirectory, "application-manifest.schema.json"))),
        ["limits"] = Json.Object(new { componentsPerRun = 64, liveRunBytes = 2_097_152, appendItems = 512, retainedRetryBatches = 256 }),
        ["cleanup"] = "Completed cards archive after a configurable review delay (default five minutes). Permanent applications remain visible. Restore cards from Archived cards; restored completed cards receive a fresh review delay."
    };
}
